@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap");
@import "@xterm/xterm/css/xterm.css";
@import "tailwindcss" source(none);
@import "tw-animate-css";

@source "../src";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans:
    -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Inter", "Segoe UI", Roboto,
    system-ui, sans-serif;
  --font-mono: "JetBrains Mono", "Cascadia Code", Consolas, "SF Mono", monospace;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: transparent;
  --color-stage: var(--stage);
  --color-panel: var(--panel);
  --color-online: var(--online);
  --color-offline: var(--offline);
  --color-warn: var(--warn);
  --color-term-prompt: var(--term-prompt);
  --color-term-path: var(--term-path);
  --color-term-info: var(--term-info);
}

:root {
  --radius: 0.25rem;
  --background: #161616;
  --panel: #222222;
  --stage: #222222;
  --foreground: #e0e0e0;
  --card: #252525;
  --card-foreground: #e0e0e0;
  --popover: #222222;
  --popover-foreground: #e0e0e0;
  --primary: #ff6b00;
  --primary-foreground: #ffffff;
  --secondary: #252525;
  --secondary-foreground: #e0e0e0;
  --muted: #181818;
  --muted-foreground: #808080;
  --accent: #2a2a2a;
  --accent-foreground: #e0e0e0;
  --destructive: #ea580c;
  --destructive-foreground: #ffffff;
  --border: #303030;
  --input: #2a2a2a;
  --ring: transparent;
  --online: #ff6b00;
  --offline: #808080;
  --warn: #fb923c;
  --term-prompt: #ff6b00;
  --term-path: #808080;
  --term-info: #808080;

  /* Rings and text-shadow cleanup (no neon text glows) */
  --tw-ring-color: transparent !important;
  --tw-ring-offset-color: transparent !important;
}

@layer base {
  * {
    border-color: var(--color-border);
  }
  *,
  *::before,
  *::after {
    text-shadow: none !important;
    -webkit-tap-highlight-color: transparent;
  }
  *:focus,
  *:focus-visible {
    outline: none !important;
  }
  html,
  body {
    height: 100%;
    background-color: #161616;
    color: #e0e0e0;
  }
  body {
    font-family: var(--font-sans);
    letter-spacing: -0.015em;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }
  button,
  input,
  textarea,
  select {
    outline: none !important;
  }
  ::-webkit-scrollbar {
    width: 5px;
    height: 5px;
  }
  ::-webkit-scrollbar-track {
    background: #161616;
  }
  ::-webkit-scrollbar-thumb {
    background: #303030;
    border-radius: 2px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #404040;
  }
}

