/* =========================================================================
   XTERM.JS CORE STYLES & BULLETPROOF HIGH-CONTRAST CURSOR
   ========================================================================= */
.xterm {
  position: relative;
  user-select: none;
  -ms-user-select: none;
  -webkit-user-select: none;
  cursor: text;
}
.xterm.focus,
.xterm:focus {
  outline: none !important;
}
.xterm .xterm-helpers {
  position: absolute;
  top: 0;
  z-index: 5;
}
.xterm .xterm-helper-textarea {
  padding: 0;
  border: 0;
  margin: 0;
  position: absolute;
  opacity: 0;
  left: -9999em;
  top: 0;
  width: 0;
  height: 0;
  z-index: -5;
  white-space: nowrap;
  overflow: hidden;
  resize: none;
}
.xterm .composition-view {
  background: #000;
  color: #fff;
  z-index: 1;
  top: 0;
  left: 0;
}
.xterm .composition-view.terminated {
  display: none;
}
.xterm .xterm-viewport {
  background-color: transparent;
  overflow-y: scroll;
  cursor: default;
  position: absolute;
  right: 0;
  left: 0;
  top: 0;
  bottom: 0;
}
.xterm .xterm-viewport::-webkit-scrollbar {
  width: 5px;
}
.xterm .xterm-viewport::-webkit-scrollbar-track {
  background: transparent;
}
.xterm .xterm-viewport::-webkit-scrollbar-thumb {
  background: #333333;
  border-radius: 2px;
}
.xterm .xterm-viewport::-webkit-scrollbar-thumb:hover {
  background: #555555;
}
.xterm .xterm-screen {
  position: relative;
}
.xterm .xterm-screen canvas {
  position: absolute;
  left: 0;
  top: 0;
}
.xterm-scroll-area {
  visibility: hidden;
}
.xterm-char-measure-element {
  display: inline-block;
  visibility: hidden;
  position: absolute;
  top: 0;
  left: -9999em;
  line-height: normal;
}
.xterm .xterm-cursor-layer {
  position: absolute;
  top: 0;
  left: 0;
}

/* Antigravity IDE Window Title Bar Drag Regions */
.app-drag-region {
  -webkit-app-region: drag;
  user-select: none;
}

.app-no-drag {
  -webkit-app-region: no-drag;
}

/* =========================================================================
   AI CHAT MESSAGE SMOOTH FADE ANIMATION
   ========================================================================= */
@keyframes aiMessageFadeIn {
  0% {
    opacity: 0;
    transform: translateY(7px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.ai-message-fade {
  animation: aiMessageFadeIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: opacity, transform;
}

@keyframes streamTokenFade {
  0% {
    opacity: 0;
    filter: blur(2px);
    transform: translateY(1px);
  }
  100% {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0);
  }
}

.stream-faded-token {
  animation: streamTokenFade 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes cursorBlinkGlow {
  0%,
  100% {
    opacity: 1;
    box-shadow: 0 0 6px rgba(0, 132, 255, 0.9);
  }
  50% {
    opacity: 0.2;
    box-shadow: none;
  }
}

.streaming-cursor {
  display: inline-block;
  width: 2px;
  height: 13px;
  margin-left: 3px;
  background-color: #0084ff;
  animation: cursorBlinkGlow 0.8s ease-in-out infinite;
  vertical-align: middle;
  border-radius: 1px;
}

